import{_ as e,C as r,o,c as h,aj as d,E as s}from"./framework.js";const g=JSON.parse('{"title":"邮箱：邮件列表 | Product / Mail | Documentation","description":"邮箱：邮件列表 in Kooboo: 在收件箱、已发送、草稿、垃圾邮件、已删除和自定义文件夹中处理邮件。列表页负责搜索、筛选、标记、移动、删除和进入邮件详情。","frontmatter":{"title":"邮箱：邮件列表 | Product / Mail | Documentation","description":"邮箱：邮件列表 in Kooboo: 在收件箱、已发送、草稿、垃圾邮件、已删除和自定义文件夹中处理邮件。列表页负责搜索、筛选、标记、移动、删除和进入邮件详情。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/mail/messages.html"}]]},"headers":[],"relativePath":"zh/product/mail/messages.md","filePath":"product/mail/messages.md","lastUpdated":1780999973000}'),i={name:"zh/product/mail/messages.md"};function l(c,t,n,b,p,m){const a=r("DocImage");return o(),h("div",null,[t[0]||(t[0]=d('<h1 id="邮箱-邮件列表" tabindex="-1">邮箱：邮件列表 <a class="header-anchor" href="#邮箱-邮件列表" aria-label="Permalink to &quot;邮箱：邮件列表&quot;">​</a></h1><blockquote><p>在收件箱、已发送、草稿、垃圾邮件、已删除和自定义文件夹中处理邮件。列表页负责搜索、筛选、标记、移动、删除和进入邮件详情。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>邮箱</strong> -&gt; 左侧 <strong>收件箱 / 已发送 / 草稿 / 垃圾邮件 / 已删除 / 文件夹</strong></td></tr><tr><td>收件箱深链</td><td><code>/_Admin/kmail/inbox</code></td></tr><tr><td>已发送深链</td><td><code>/_Admin/kmail/sent</code></td></tr><tr><td>搜索结果深链</td><td><code>/_Admin/kmail/searchEmail?flag=common&amp;keyword={keyword}</code></td></tr><tr><td>前端路由</td><td><code>/kmail/inbox</code>、<code>/kmail/sent</code>、<code>/kmail/draft</code>、<code>/kmail/spam</code>、<code>/kmail/trash</code>、<code>/kmail/folder</code>、<code>/kmail/searchEmail</code></td></tr></tbody></table>',4)),s(a,{src:"/product/mail/messages-overview.png",alt:"邮箱邮件列表：工具栏、筛选和邮件行",width:"1120"}),t[1]||(t[1]=d('<h2 id="左侧菜单" tabindex="-1">左侧菜单 <a class="header-anchor" href="#左侧菜单" aria-label="Permalink to &quot;左侧菜单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td><code>写邮件</code></td><td>进入撰写页，保留当前地址或返回目录信息</td></tr><tr><td>收件箱</td><td>展示总未读数；展开后可按邮箱地址筛选</td></tr><tr><td>已发送</td><td>展示已发送地址分组；展开后可按地址筛选</td></tr><tr><td>文件夹</td><td>有自定义文件夹时显示，可创建、展开、重命名或删除文件夹</td></tr><tr><td>草稿 / 垃圾邮件 / 已删除</td><td>固定系统目录</td></tr><tr><td>Calendar</td><td>左侧底部固定入口，进入邮箱日历</td></tr><tr><td>Settings</td><td>左侧底部固定入口，进入邮箱设置并默认打开邮箱地址页</td></tr></tbody></table><p>点击当前已激活菜单时，页面会刷新列表和未读数。进入邮箱页后，顶部邮箱红点会被清除。</p><h2 id="列表工具栏" tabindex="-1">列表工具栏 <a class="header-anchor" href="#列表工具栏" aria-label="Permalink to &quot;列表工具栏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td>刷新</td><td>重新加载当前目录邮件，并刷新对应未读数</td></tr><tr><td>搜索框</td><td>输入关键字并回车，进入搜索结果页</td></tr><tr><td>全选下拉</td><td>可选择全部、已读、未读</td></tr><tr><td>删除</td><td>非 Trash 目录会移动到已删除；Trash 中会永久删除</td></tr><tr><td><code>Mark as</code></td><td>批量标记为已读或未读</td></tr><tr><td><code>Move to</code></td><td>批量移动到收件箱、已发送、垃圾邮件或自定义文件夹</td></tr><tr><td><code>Restore to</code></td><td>在已删除目录中用于恢复到其它目录</td></tr><tr><td><code>Not spam</code></td><td>在垃圾邮件目录中将选中邮件移回收件箱</td></tr></tbody></table><p>列表支持滚动加载更多邮件。若当前目录只剩少量邮件，移动或删除后会自动补拉下一批。</p><h2 id="邮件行" tabindex="-1">邮件行 <a class="header-anchor" href="#邮件行" aria-label="Permalink to &quot;邮件行&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>选择框</td><td>勾选后可批量操作</td></tr><tr><td>已读图标</td><td>点击可在已读 / 未读之间切换</td></tr><tr><td>发件人 / 收件人</td><td>收件箱显示发件人；已发送和草稿显示收件人</td></tr><tr><td>主题</td><td>空主题显示为“无主题”；有附件时显示附件图标和最多 3 个附件名</td></tr><tr><td>时间</td><td>显示邮件时间</td></tr><tr><td>投递状态</td><td>已发送邮件可能显示投递状态图标，点击可查看投递日志</td></tr></tbody></table><p>点击邮件主体区域会进入详情页。未读邮件打开详情时会自动标记为已读。</p><h2 id="邮件详情" tabindex="-1">邮件详情 <a class="header-anchor" href="#邮件详情" aria-label="Permalink to &quot;邮件详情&quot;">​</a></h2><p>详情页深链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/kmail/content?folder={folder}&amp;messageId={messageId}</span></span></code></pre></div><p>详情页顶部操作：</p><table tabindex="0"><thead><tr><th>操作</th><th>显示条件</th><th>说明</th></tr></thead><tbody><tr><td>返回</td><td>始终显示</td><td>返回原目录或搜索结果</td></tr><tr><td>再次编辑</td><td>已发送、草稿</td><td>复制当前邮件内容进入撰写页</td></tr><tr><td>回复 / 全部回复 / 转发</td><td>非草稿</td><td>带原邮件上下文进入撰写页</td></tr><tr><td>删除</td><td>始终显示</td><td>按当前目录规则移入 Trash 或永久删除</td></tr><tr><td>移动</td><td>非草稿</td><td>移动到其它系统目录或自定义文件夹</td></tr></tbody></table><p>详情区可展开收件人详情，查看附件、会议邀请、邮件原文和导出邮件。<code>显示邮件原文</code> 会在新标签页打开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/original-message?messageId={messageId}</span></span></code></pre></div><p>若邮件包含日程邀请，详情页会显示接受、拒绝、暂定和重新选择等操作。</p><h2 id="文件夹" tabindex="-1">文件夹 <a class="header-anchor" href="#文件夹" aria-label="Permalink to &quot;文件夹&quot;">​</a></h2><p>文件夹只在已有自定义文件夹时显示。点击文件夹标题旁的加号可以新建文件夹；在文件夹项上可重命名或删除。</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>新建</td><td>填写文件夹名，最长 50 个字符</td></tr><tr><td>重命名</td><td>修改当前文件夹名；子文件夹路径会随父级变化</td></tr><tr><td>删除</td><td>有子文件夹时不能直接删除，需先删除子文件夹</td></tr><tr><td>移动邮件</td><td><code>Move to</code> 下拉会包含自定义文件夹树</td></tr></tbody></table><p>文件夹支持层级路径。界面保存的是完整路径，例如 <code>Projects/Kooboo</code>。</p><h2 id="搜索邮件" tabindex="-1">搜索邮件 <a class="header-anchor" href="#搜索邮件" aria-label="Permalink to &quot;搜索邮件&quot;">​</a></h2><p>右上搜索框输入关键字后回车，会进入搜索结果页。搜索结果行会额外显示邮件所在目录，点击目录名称可跳回对应目录。</p><p>前端代码里保留了高级搜索弹窗模型，字段包括关键字位置、发件人、收件人、日期范围、目录和已读状态；但当前高级搜索入口在界面中被注释隐藏。日常操作以右上普通搜索为准。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>快速处理新邮件</td><td>收件箱 -&gt; 打开未读邮件 -&gt; 回复或移动 -&gt; 返回列表</td></tr><tr><td>归档项目邮件</td><td>新建文件夹 -&gt; 勾选邮件 -&gt; <code>Move to</code> -&gt; 选择文件夹</td></tr><tr><td>清理垃圾邮件</td><td>垃圾邮件 -&gt; 勾选误判邮件 -&gt; <code>Not spam</code>；其它邮件删除</td></tr><tr><td>追踪已发邮件</td><td>已发送 -&gt; 查看投递状态 -&gt; 打开投递日志</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./compose.html">撰写邮件</a></td><td>写邮件、回复、转发、草稿</td></tr><tr><td><a href="./calendar.html">日历</a></td><td>邮箱日程与会议邀请</td></tr><tr><td><a href="./addresses.html">邮箱地址</a></td><td>配置发件地址和默认地址</td></tr><tr><td><a href="/kb-docs/zh/api/mail/">k.mail</a></td><td>服务端邮件 API</td></tr></tbody></table>',28))])}const k=e(i,[["render",l]]);export{g as __pageData,k as default};
